mapper.select:
SELECT *, count(*) OVER()::integer AS total FROM credential_handles
WHERE organization_id = #{organizationId}
ORDER BY created_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE credential_handles SET name = COALESCE(#{name}, name), status = COALESCE(#{status}, status),
  metadata = COALESCE(#{metadata, typeHandler=com.kross.support.JsonbTypeHandler}, metadata), updated_at = now()
WHERE organization_id = #{organizationId} AND id = #{id}

mapper.select:
SELECT *, count(*) OVER()::integer AS total FROM model_profiles
WHERE organization_id = #{organizationId}
ORDER BY created_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

mapper.insert:
INSERT INTO schedules
  (id, organization_id, project_id, task_id, cron_expression, timezone, selected_source_ids,
   next_run_at, concurrency_policy, external_action_policy, created_by)
SELECT #{id}, t.organization_id, t.project_id, t.id, #{cron}, #{timezone},
       #{sourceIds, typeHandler=com.kross.support.JsonbTypeHandler}, #{nextRunAt}, 'skip', 'draft_only', #{userId}
FROM tasks t WHERE t.organization_id = #{organizationId} AND t.project_id = #{projectId} AND t.id = #{taskId}
